import {createHash}from'node:crypto';import{readFileSync}from'node:fs';import{resolve}from'node:path';import{describe,expect,it}from'vitest';
import{candidateCompanies}from'../../src/data/companyRegistry';import{buildStagedSourceCrawlPlans,sourcePlanConfigSha256}from'../../src/crawler/sourcePlan';
import{assertExistingDatabaseMigrationHistory,assertExistingDatabaseMigrationManifest}from'../../src/db/existingDatabasePreflight';import{listCurrentPrismaMigrations}from'../../src/db/prismaMigrationManifest';
const prior='20261001233000_verified_date_source_policy',next='20261002001500_bms_mainland_geography_policy';
const read=(n:string)=>readFileSync(resolve('prisma/migrations',n,'migration.sql'),'utf8'),body=(s:string)=>s.slice(s.indexOf('CREATE OR REPLACE FUNCTION'),s.indexOf('\nCOMMIT;'));
describe('BMS append-only SQL43 registration',()=>{
 it('adds only the exact BMS tuple and guards the unchanged SQL42 function',()=>{const old=read(prior),sql=read(next),p=buildStagedSourceCrawlPlans(candidateCompanies).find(p=>p.source.id==='source-bms-china-social')!;const tuple=`                ('${p.source.id}','${p.company.id}','${sourcePlanConfigSha256(p)}'),\n`;expect(body(sql).split(tuple)).toHaveLength(2);expect(body(sql).replace(tuple,'')).toBe(body(old));const definition=body(old).slice(0,body(old).lastIndexOf('$function$'))+'$function$\n';expect(sql).toContain(`<> '${createHash('md5').update(definition).digest('hex')}' THEN`);expect(sql).toContain("BEGIN;\nSET LOCAL lock_timeout = '5s';\nSET LOCAL statement_timeout = '30s';");});
 it('pins only the exact43 history and preserves the exact36–42 histories',()=>{const files=listCurrentPrismaMigrations(process.cwd()).filter(m=>m.migrationName<=next);expect(files).toHaveLength(43);for(let n=36;n<=43;n++)expect(()=>assertExistingDatabaseMigrationManifest(files.slice(0,n))).not.toThrow();const rows=files.map(m=>({migration_name:m.migrationName,checksum:m.checksum,finished_at:new Date(),rolled_back_at:null}));expect(()=>assertExistingDatabaseMigrationHistory(rows,files)).not.toThrow();for(const bad of [rows.slice(0,-1),rows.map((r,i)=>i===42?{...r,checksum:'0'.repeat(64)}:r),rows.map((r,i)=>i===42?{...r,finished_at:null}:r),rows.map((r,i)=>i===42?{...r,rolled_back_at:new Date()}:r),[...rows,rows[42]!]])expect(()=>assertExistingDatabaseMigrationHistory(bad,files)).toThrow();expect(()=>assertExistingDatabaseMigrationManifest(files.map((m,i)=>i===42?{...m,checksum:'0'.repeat(64)}:m))).toThrow();});
});
